CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Tile dimensions for output
#define TILE_H 8
#define TILE_W 16

// Kernel specialized for arbitrary kH x kW with shared memory input halo reuse.
// Each block covers one (n, c_out) pair and a TILE_H x TILE_W output tile.
// Input halo tile per input channel: (TILE_H*sH + (kH-1)*dH) x (TILE_W*sW + (kW-1)*dW)
// We load per c_in slice to bound shared memory usage.

__global__ void conv2d_smem_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int C_in, int C_out,
    int H_in, int W_in,
    int H_out, int W_out,
    int kH, int kW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w)
{
    // blockIdx.x = tile col index, blockIdx.y = tile row index
    // blockIdx.z encodes (n * C_out + c_out)
    int nc_out = blockIdx.z;
    int n      = nc_out / C_out;
    int c_out  = nc_out % C_out;

    int tile_row = blockIdx.y;
    int tile_col = blockIdx.x;

    // Output pixel this thread is responsible for
    int oh = tile_row * TILE_H + threadIdx.y;
    int ow = tile_col * TILE_W + threadIdx.x;

    // Shared memory tile covers the input halo for this output tile
    // smem_h = TILE_H * stride_h + (kH-1)*dil_h
    // smem_w = TILE_W * stride_w + (kW-1)*dil_w  + 1 (bank conflict padding)
    // We'll use dynamic sizing via compile-time max bounds or just use a fixed
    // allocation large enough. For the benchmark: kH=5,kW=9,stride=1,dil=1 gives
    // smem_h=12, smem_w=24+1=25. We'll generalize with a shared mem declaration
    // sized at runtime via dynamic shared memory.
    extern __shared__ float smem[]; // size = smem_h * smem_w_padded

    int smem_h = TILE_H * stride_h + (kH - 1) * dil_h;
    int smem_w = TILE_W * stride_w + (kW - 1) * dil_w;
    int smem_w_pad = smem_w + 1; // +1 for bank conflict avoidance

    // Top-left input coordinate for this tile
    int in_row_base = tile_row * TILE_H * stride_h - pad_h;
    int in_col_base = tile_col * TILE_W * stride_w - pad_w;

    int threads_per_block = TILE_H * TILE_W;
    int tid = threadIdx.y * TILE_W + threadIdx.x;
    int smem_size = smem_h * smem_w_pad;

    float acc = 0.0f;

    for (int c_in = 0; c_in < C_in; c_in++) {
        // Cooperative load of input halo tile into shared memory
        const float* in_ptr = input + (n * C_in + c_in) * H_in * W_in;
        for (int idx = tid; idx < smem_size; idx += threads_per_block) {
            int sr = idx / smem_w_pad;
            int sc = idx % smem_w_pad;
            if (sc < smem_w) {
                int gr = in_row_base + sr;
                int gc = in_col_base + sc;
                if (gr >= 0 && gr < H_in && gc >= 0 && gc < W_in) {
                    smem[idx] = in_ptr[gr * W_in + gc];
                } else {
                    smem[idx] = 0.0f;
                }
            }
        }
        __syncthreads();

        if (oh < H_out && ow < W_out) {
            // Accumulate over kernel window
            const float* w_ptr = weight + (c_out * C_in + c_in) * kH * kW;
            int local_row = threadIdx.y * stride_h;
            int local_col = threadIdx.x * stride_w;
            #pragma unroll
            for (int kh = 0; kh < 5; kh++) {
                #pragma unroll
                for (int kw = 0; kw < 9; kw++) {
                    int sr = local_row + kh * dil_h;
                    int sc = local_col + kw * dil_w;
                    acc += smem[sr * smem_w_pad + sc] * w_ptr[kh * kW + kw];
                }
            }
        }
        __syncthreads();
    }

    if (oh < H_out && ow < W_out) {
        output[(n * C_out + c_out) * H_out * W_out + oh * W_out + ow] = acc;
    }
}

// Generic fallback for non-5x9 kernels using simple per-pixel approach
__global__ void conv2d_generic_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int C_in, int C_out,
    int H_in, int W_in,
    int H_out, int W_out,
    int kH, int kW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * H_out * W_out;
    if (idx >= total) return;

    int ow   = idx % W_out; idx /= W_out;
    int oh   = idx % H_out; idx /= H_out;
    int cout = idx % C_out; idx /= C_out;
    int n    = idx;

    float acc = 0.0f;
    for (int cin = 0; cin < C_in; cin++) {
        for (int kh = 0; kh < kH; kh++) {
            for (int kw = 0; kw < kW; kw++) {
                int ih = oh * stride_h - pad_h + kh * dil_h;
                int iw = ow * stride_w - pad_w + kw * dil_w;
                if (ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
                    acc += input[(n * C_in + cin) * H_in * W_in + ih * W_in + iw]
                         * weight[(cout * C_in + cin) * kH * kW + kh * kW + kw];
                }
            }
        }
    }
    output[(n * C_out + cout) * H_out * W_out + oh * W_out + ow] = acc;
}

torch::Tensor conv2d_smem_forward(
    torch::Tensor input,
    torch::Tensor weight,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");

    int N    = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);
    int C_out = weight.size(0);
    int kH   = weight.size(2);
    int kW   = weight.size(3);

    int H_out = (H_in + 2 * pad_h - dil_h * (kH - 1) - 1) / stride_h + 1;
    int W_out = (W_in + 2 * pad_w - dil_w * (kW - 1) - 1) / stride_w + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());

    if (kH == 5 && kW == 9) {
        // Use shared-memory tiled path
        dim3 block(TILE_W, TILE_H);
        int grid_x = (W_out + TILE_W - 1) / TILE_W;
        int grid_y = (H_out + TILE_H - 1) / TILE_H;
        int grid_z = N * C_out;
        dim3 grid(grid_x, grid_y, grid_z);

        int smem_h = TILE_H * stride_h + (kH - 1) * dil_h;
        int smem_w = TILE_W * stride_w + (kW - 1) * dil_w;
        int smem_w_pad = smem_w + 1;
        int smem_bytes = smem_h * smem_w_pad * sizeof(float);

        conv2d_smem_kernel<<<grid, block, smem_bytes>>>(
            input.data_ptr<float>(),
            weight.data_ptr<float>(),
            output.data_ptr<float>(),
            N, C_in, C_out,
            H_in, W_in, H_out, W_out,
            kH, kW,
            stride_h, stride_w,
            pad_h, pad_w,
            dil_h, dil_w);
    } else {
        // Generic fallback
        int total = N * C_out * H_out * W_out;
        int block = 256;
        int grid = (total + block - 1) / block;
        conv2d_generic_kernel<<<grid, block>>>(
            input.data_ptr<float>(),
            weight.data_ptr<float>(),
            output.data_ptr<float>(),
            N, C_in, C_out,
            H_in, W_in, H_out, W_out,
            kH, kW,
            stride_h, stride_w,
            pad_h, pad_w,
            dil_h, dil_w);
    }

    return output;
}
# <<<END_IMPROVE>>>
