# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_H 8
#define TILE_W 32
#define SMEM_PAD 1

__global__ void conv2d_nchw_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int H_out, int W_out,
    int kH, int kW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w,
    bool has_bias)
{
    extern __shared__ float smem[];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int bz = blockIdx.z;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int n = bz / C_out;
    const int c_out = bz % C_out;
    const int oh_base = by * TILE_H;
    const int ow_base = bx * TILE_W;

    const int oh = oh_base + ty;
    const int ow = ow_base + tx;

    float acc = 0.0f;

    if (oh < H_out && ow < W_out) {
        for (int c_in = 0; c_in < C_in; ++c_in) {
            const int smem_h = TILE_H + kH - 1;
            const int smem_w = TILE_W + kW - 1;
            const int smem_stride = smem_w + SMEM_PAD;

            for (int load_idx = ty * TILE_W + tx; load_idx < smem_h * smem_w; load_idx += TILE_H * TILE_W) {
                const int smem_y = load_idx / smem_w;
                const int smem_x = load_idx % smem_w;

                const int ih = oh_base * stride_h - pad_h + smem_y * dilation_h;
                const int iw = ow_base * stride_w - pad_w + smem_x * dilation_w;

                float val = 0.0f;
                if (ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
                    val = input[((n * C_in + c_in) * H_in + ih) * W_in + iw];
                }
                smem[smem_y * smem_stride + smem_x] = val;
            }
            __syncthreads();

            const int weight_offset = (c_out * C_in + c_in) * kH * kW;

            #pragma unroll
            for (int kh = 0; kh < kH; ++kh) {
                #pragma unroll
                for (int kw = 0; kw < kW; ++kw) {
                    const int smem_y = ty * stride_h + kh * dilation_h;
                    const int smem_x = tx * stride_w + kw * dilation_w;
                    const float in_val = smem[smem_y * smem_stride + smem_x];
                    const float w_val = __ldg(&weight[weight_offset + kh * kW + kw]);
                    acc += in_val * w_val;
                }
            }
            __syncthreads();
        }

        if (has_bias) {
            acc += __ldg(&bias[c_out]);
        }

        output[((n * C_out + c_out) * H_out + oh) * W_out + ow] = acc;
    }
}

torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w,
    int groups)
{
    const int N = input.size(0);
    const int C_in = input.size(1);
    const int H_in = input.size(2);
    const int W_in = input.size(3);
    const int C_out = weight.size(0);
    const int kH = weight.size(2);
    const int kW = weight.size(3);

    const int H_out = (H_in + 2 * pad_h - dilation_h * (kH - 1) - 1) / stride_h + 1;
    const int W_out = (W_in + 2 * pad_w - dilation_w * (kW - 1) - 1) / stride_w + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());

    if (groups != 1 || stride_h != 1 || stride_w != 1 || dilation_h != 1 || dilation_w != 1) {
        return torch::conv2d(input, weight, bias, {stride_h, stride_w}, {pad_h, pad_w}, {dilation_h, dilation_w}, groups);
    }

    const int smem_h = TILE_H + kH - 1;
    const int smem_w = TILE_W + kW - 1;
    const int smem_size = smem_h * (smem_w + SMEM_PAD) * sizeof(float);

    dim3 block(TILE_W, TILE_H);
    dim3 grid((W_out + TILE_W - 1) / TILE_W, (H_out + TILE_H - 1) / TILE_H, N * C_out);

    const bool has_bias = bias.defined();
    const float* bias_ptr = has_bias ? bias.data_ptr<float>() : nullptr;

    conv2d_nchw_kernel<<<grid, block, smem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, H_out, W_out,
        kH, kW,
        stride_h, stride_w,
        pad_h, pad_w,
        dilation_h, dilation_w,
        has_bias
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

